const CACHE="tiger-gto-v25",FILES=["presentation.js","study-plan.js","import-ui.js","exploit-ranges.js","exploit-range-ui.js","data/four-handed-baselines.json","villain-ui.js","notebook.js","spots.js","data/opponent_profiles.json","data/villain_spots_seed.json","pixel.woff2", "equity.js", "equity-ui.js", "display.woff2", "./", "index.html", "style.css", "app.js", "icon.svg", "manifest.json", "data/learn.json", "data/index.json", "data/three-SB.json", "data/open-CO-LJ.json", "data/open-SB-HJ.json", "data/open-CO-HJ.json", "data/open-SB-CO.json", "data/open-SB-LJ.json", "data/rfi-CO.json", "data/three-HJ.json", "data/open-HJ-LJ.json", "data/open-BB-BTN.json", "data/three-BTN.json", "data/open-BB-HJ.json", "data/open-BB-SB.json", "data/open-BTN-HJ.json", "data/rfi-BTN.json", "data/three-CO.json", "data/rfi-SB.json", "data/open-BTN-LJ.json", "data/rfi-LJ.json", "data/three-LJ.json", "data/open-BB-LJ.json", "data/sources.json", "data/open-SB-BTN.json", "data/open-BB-CO.json", "data/rfi-HJ.json", "data/open-BTN-CO.json"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('tiger-gto-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('message',event=>{if(event.data==='SKIP_WAITING')self.skipWaiting()});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(res=>{if(res.ok){let copy=res.clone();caches.open(CACHE).then(c=>c.put(event.request,copy))}return res}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('index.html'):Response.error()))))});
